dict.string:
.navbar {
	font-family: Arial, sans-serif;
	font-size: .9em;
	color: #000;	
	margin: 0px;
}

.navbar-bg {
	text-align: left;
	padding: 0px;
}

.navbar-bg ul {
	list-style: none;
	margin: 0px;
	padding: 0px;
}


li {
	list-style-type: none;
	float: left;
	margin: 0px 2px 4px 0;
	background-color: #fff;
	padding: 6px 16px 6px 16px;
}

li a {
	text-decoration: none;
	color: #000;
	text-shadow: -1px 0px 1px #B3B7B4;
}

li a:visited {
	text-decoration: none;
	color: #000;
	text-shadow: -1px 0px 1px #B3B7B4;
}

li a:hover{
 	color: #D90000;
	text-decoration: none;}


li.current-page a{	color: #D90000;
	font-weight: bold;
	text-decoration: none;}
